import java.util.ArrayList;
import java.util.List;

public class Voiture{
    public static void main(String[] args) {
        List<Voiture> voitures = new ArrayList<>();

        // Ajout élément après élément
        voitures.add(new Voiture("Swift", 10));
        voitures.add(new Voiture("Renault", 20));

        // Ajout de tous les éléments en une seule fois
        var voitures2 = List.of(new Voiture("Ford", 15), new Voiture("Fiat", 10));

        System.out.println(voitures);
        System.out.println(voitures2);

        // Accéder à un élément de la liste
        var uneVoiture = voitures.get(0);
        System.out.println(uneVoiture);

        // Instanciation d'objets de type Voiture
        var v1 = new Voiture("v1", 0);
        var v2 = new Voiture("v2", 0);
        var v3 = new Voiture("v3", 0);
        var v4 = new Voiture("v4", 0);

        List<Voiture> atelier = new ArrayList<>();
        atelier.add(v1);
        atelier.add(v2);
        atelier.add(v3);
        atelier.add(v4);

        // Supression de la 3ième voiture => index 2
        Voiture voitureSupprimee = atelier.remove(2);
        System.out.println("La voiture " + voitureSupprimee.getMarque() + "a été réparée.");

        // Supression de la voiture v2
        boolean aEteSupprimee = atelier.remove(v2);
        if (aEteSupprimee) {
            System.out.println("La voiture " + v2.getMarque() + " a été réparée.");
        }
        System.out.println(atelier); // v1 et v4 sont respectivement à la position 0 et 1

        // Parcours de la liste avec la boucle for-each
        for (Voiture voiture : atelier) {
            System.out.println(voiture);
        }
    }
}

