import java.util.HashMap;
import java.util.Map;

public class DemoMap {
    public static void main(String[] args) {

        Map<String, Voiture> atelier = new HashMap<>();

        // Instanciation d'objets de type Voiture
        var v1 = new Voiture("v1", 0);
        var v2 = new Voiture("v2", 0);
        var v3 = new Voiture("v3", 0);
        var v4 = new Voiture("v4", 0);

        // Ajout des voitures dans l'atelier
        atelier.put("AB-123-CD", v1);
        atelier.put("ET-456-RH", v2);
        atelier.put("YU-789-AN", v3);
        atelier.put("CO-951-DN", v4);
        atelier.put("ZE-456-RT", v5);
        atelier.put("UG-753-MA", v6);

        // Accéder à un élément de la Map
        var uneVoiture = atelier.get("YU-789-AN");
        System.out.println(uneVoiture);

        // Ajout d'une voitures dans l'atelier
        var v7 = new Voiture("Renault", 15);
        atelier.put("UG-753-MA", v7); // Modification de la valeur associée à une clé existante
        atelier.put("AZ-854-BH", v5); // Ajout d'une nouvelle association (nouvelle clé, valeur existante)

        // Supression de la voiture associée à la clé "ET-456-RH"
        Voiture voitureSupprimee = atelier.remove("ET-456-RH");
        System.out.println("La voiture " + voitureSupprimee.getMarque() + " a été réparée.");

        System.out.println(atelier);

        // Parcours de l'ensemble des clés du Map
        for (String cle : atelier.keySet()) {
            System.out.println(cle);
        }

        // Parcours de l'ensemble des valeurs du Map
        for (Voiture voiture : atelier.values()) {
            System.out.println(voiture); // affichage du toString de chaque voiture
        }

        // Parcours de l'ensemble des paires clé-valeur du Map
        for (var paire : atelier.entrySet()) {
            System.out.println("La clé est " + paire.getKey() // valeur de la clé : immatriculation 
            + " la valeur est " + paire.getValue()); // toString de la voiture
        }
    }
}

