                    break;
                case VENDREDI:
                    System.out.println(jour.getLibelle() + " : " + "13:00 - 19:00");
                    break;
                case SAMEDI:
                case DIMANCHE:
                    System.out.println(jour.getLibelle() + " : " + "10:00 - 14:00");
                    break;
             }
        }

        //Expressions switch
        public static void afficherHoraire(JoursSemaine jour) {

            String horaire = switch (jour) {
                case LUNDI -> jour.getLibelle() + " : " + "Fermé";
                case MARDI -> jour .getLibelle()+ " : 10:00 - 19:00";
                case MERCREDI -> jour.getLibelle() + " : 13:00 - 19:00";
