    public Animal(String nom, int age) {
        this.nom = nom;
        this.age = age;
    }

    public void afficherAge() {
        System.out.println("Je m'appelle " + nom + ", j'ai " + age + " an(s).");
    }
    public void crier() {
        System.out.println("Je crie : Je suis un animal !");
    }
}

public class Chien extends Animal {

    public Chien(String nom, int age) {
        super(nom, age); // super est l'équivalent du `this` pour référencer le parent
    }

    @Override
    public void crier() {
        System.out.println("Wouf, Wouf !");
    }

    public int calculerAgeSpecifique() {
        int ageEquivalentHumain = age * 7; // Erreur compilation : "The field Animal.age is not visible"
        return ageEquivalentHumain;
    }
}

public class Chat extends Animal {

    public Chat(String nom, int age) {
        super(nom, age);
    }

    @Override
    public void crier() {
        System.out.println("Miaouu ...");
    }
}

public class App {
    public static void main(String[] args) {

        List<Animal> animaux = new ArrayList<>();

        var fido = new Chien("Fido", 5);
        animaux.add(fido);

        var felix = new Chat("Félix", 3);
        animaux.add(felix);

        for (Animal animal : animaux) {
            animal.afficherAge();
            animal.crier();
        }

        System.out.println("Age humain de fido : " + fido.calculerAgeSpecifique() + " ans.");
    }
}

